func Gia_ManReadMiniAig(pFileName string) *Gia_Man_t {
    var p *Mini_Aig_t  = Mini_AigLoad( pFileName );
    var pGia *Gia_Man_t  = Gia_ManFromMiniAig( p, nil );
    ABC_FREE( pGia.pName );
